p='jobs/search-reindex-job.ts'
s=open(p).read()
i=s.index('export async function runSearchReindexJob')
s=s[:i]+'''export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteAllSearchDocuments(orgId);

    const liveProjects = new Set<string>();
    let projectCursor: string | null = null;
    do {
      const page = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
        includeArchived: false,
      });
      for (const project of page.items) {
        if (project.archivedAt) continue;
        liveProjects.add(project.id);
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      projectCursor = page.nextCursor;
    } while (projectCursor);

    let issueCursor: string | null = null;
    do {
      const page = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
        includeArchived: false,
      });
      for (const issue of page.items) {
        if (issue.archivedAt || !liveProjects.has(issue.projectId)) continue;
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          let commentCursor: string | null = null;
          do {
            const comments = await commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: false,
              limit: PAGE_SIZE,
              cursor: commentCursor,
            });
            for (const comment of comments.items) {
              if (comment.archivedAt) continue;
              await indexComment(orgId, comment);
              result.processed += 1;
            }
            commentCursor = comments.nextCursor;
          } while (commentCursor);
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      issueCursor = page.nextCursor;
    } while (issueCursor);
  });
}
